    "summaryZh": "2026-07-07 百度热搜第 13 名，热度 675.7万。7月6日至7日，广西横州市云表镇邓圩村因洪涝致养蛇场被冲毁，导致多条蛇外逃，包括眼镜蛇等毒蛇。当地村民称目前已造成10余名村民被咬伤，部分伤者因交通中断送医困难。横州市应急管理局回应称，救援人员已前往一线处置，暂未收到处理反馈，具体情况等待官方通报。",
